    view?: ButtonView;
    removeAfterClick?: boolean;
};
export type ToastProps = {
    name: string;
    title?: string;
    className?: string;
    autoHiding?: number | false;
    content?: React.ReactNode;
    theme?: ToastTheme;
    isClosable?: boolean;
    actions?: (() => React.ReactElement) | ToastAction[];
    onClose?: () => void;
